func outlinedText(text string, cx, baseline, maxWidth, size float64) string {
	width := 0.
	for _, r := range text {
		width += answerGlyphs[r].width
	}
	scale := min(size/100, maxWidth/max(1, width))
	var out strings.Builder
	fmt.Fprintf(&out, `<g data-outline-text="%s" transform="translate(%.4f %.4f) scale(%.6f)">`, html.EscapeString(text), cx-width*scale/2, baseline, scale)
	x := 0.
	for _, r := range text {
		g := answerGlyphs[r]
		fmt.Fprintf(&out, `<path transform="translate(%.3f 0)" d="%s"/>`, x, g.path)
		x += g.width
	}
	out.WriteString(`</g>`)
	return out.String()
}
